css:
.hqr-sheet { display: flex; flex-wrap: wrap; gap: 4mm; align-content: flex-start; }
.hqr-card {
    position: relative;
    width: 85.6mm; height: 53.98mm;
    border-radius: 3.5mm; overflow: hidden;
    background: linear-gradient(135deg, #3b2417 0%, #5a3620 45%, #4e342e 100%);
    color: #f7ecdd;
    font-family: "Helvetica Neue", Arial, sans-serif;
    box-shadow: 0 0 0 0.3mm rgba(0,0,0,0.15);
    page-break-inside: avoid; break-inside: avoid;
}
.hqr-accent {
    position: absolute; top: 0; left: 0; right: 0; height: 2mm;
    background: linear-gradient(90deg, #d7a96b 0%, #f0c98a 50%, #d7a96b 100%);
}
.hqr-body { display: flex; height: 100%; padding: 5mm 4.5mm 4mm; box-sizing: border-box; gap: 3mm; }
.hqr-info { display: flex; flex-direction: column; flex: 1 1 auto; min-width: 0; }
.hqr-brand { font-size: 7pt; letter-spacing: 0.6pt; text-transform: uppercase; color: #e6c79a; font-weight: 700; }
.hqr-role { font-size: 6pt; letter-spacing: 1.5pt; text-transform: uppercase; color: #c9a06f; margin-top: 0.4mm; }
.hqr-name {
    font-size: 13.5pt; font-weight: 800; line-height: 1.1; margin-top: auto; margin-bottom: 2mm;
    color: #ffffff; word-break: break-word;
    display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.hqr-fields { display: flex; flex-direction: column; gap: 1.4mm; }
.hqr-field { display: flex; flex-direction: column; }
.hqr-label { font-size: 5.5pt; letter-spacing: 1pt; text-transform: uppercase; color: #b89066; }
.hqr-value { font-size: 9.5pt; font-weight: 700; color: #f7ecdd; line-height: 1.1; }
.hqr-hid { color: #f0c98a; }
.hqr-qrbox { display: flex; flex-direction: column; align-items: center; justify-content: center; }
.hqr-qr {
    width: 24mm; height: 24mm; background: #fff;
    padding: 1.6mm; border-radius: 2mm; box-sizing: border-box;
}
.hqr-qrcap { margin-top: 1.4mm; font-size: 6pt; letter-spacing: 0.4pt; color: #e6c79a; font-weight: 600; }
@media print { .hqr-card { box-shadow: none; } }
